#include <stdio.h>

#define MAX_N 100005
#define MAX_EDGES 1200005

int head[MAX_N];
int to[MAX_EDGES];
int next[MAX_EDGES];
int color[MAX_N];
int queue[MAX_N];

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    for (int i = 1; i <= N; i++) {
        head[i] = -1;
        color[i] = -1;
    }

    int edgeCnt = 0;
    for (int i = 1; i <= N; i++) {
        int M;
        scanf("%d", &M);
        for (int j = 0; j < M; j++) {
            int X;
            scanf("%d", &X);
            // add i -> X
            to[edgeCnt] = X;
            next[edgeCnt] = head[i];
            head[i] = edgeCnt;
            edgeCnt++;
            // add X -> i
            to[edgeCnt] = i;
            next[edgeCnt] = head[X];
            head[X] = edgeCnt;
            edgeCnt++;
        }
    }

    int qhead = 0, qtail = 0;
    for (int i = 1; i <= N; i++) {
        if (color[i] == -1) {
            color[i] = 0;
            queue[qtail++] = i;
            while (qhead < qtail) {
                int u = queue[qhead++];
                for (int e = head[u]; e != -1; e = next[e]) {
                    int v = to[e];
                    if (color[v] == -1) {
                        color[v] = 1 - color[u];
                        queue[qtail++] = v;
                    }
                }
            }
        }
    }

    int first = 1;
    for (int i = 1; i <= N; i++) {
        if (color[i] == 0) {
            if (!first) printf(" ");
            printf("%d", i);
            first = 0;
        }
    }
    printf("\n");

    first = 1;
    for (int i = 1; i <= N; i++) {
        if (color[i] == 1) {
            if (!first) printf(" ");
            printf("%d", i);
            first = 0;
        }
    }
    printf("\n");

    return 0;
}
```

